def depth(t):
    if t in memo:
        return memo[t]
    if t in stack:
        raise SystemExit(f"CYCLE through {t}")
    stack.add(t)
    d = 1 + max([depth(x) for x in tasks[t]["hard"] if x in tasks] or [0])
    stack.discard(t)
    memo[t] = d
    return d


